SELECT 'gongkao', '四面体', 'kp-xc-tutui-spatial-tetra', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"四面体"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"四面体展开图是三角形拼接，核心方法与六面体类似：找相邻面、排除相对面。四面体只有 4 个面，判断相对面更简单。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、题型识别"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"三角形展开图"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"四面体立体图"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心方法"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"四面体有 4 个面，任意两个面都相邻（没有相对面）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"公共边法：相邻面的公共边两侧图案位置不变"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"时针法：三个相邻面的时针方向在展开图和立体图中一致"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、易错点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fef2f2","borderColor":"#ef4444","icon":"⚠️"},"content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"四面体没有相对面！任意两面都相邻，不能用相对面排除法"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"展开图中三角形的排列方式影响折叠结果"}]}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"四面体在图形推理中占比约 3%，属于低频考点。重点掌握公共边法，注意四面体没有相对面这一特殊性质。"}]}]}]}$$ AS jsonb), NULL, '图形推理立体类-四面体的核心考点：四面体展开图、公共边法、时针法。', category_node.id, CAST('["图形推理", "立体空间", "四面体", "展开图"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xc_tuTui_spatial_tetra", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
